WITH g AS (
SELECT 'stg_account_alt_ccy_values' AS stg, svc_is_amla AS is_amla,
  IF(svc_is_amla, DATE_TRUNC(FIC_MIS_DATE, MONTH), DATE_TRUNC(svc_src, MONTH)) AS grp_month,
  MIN(svc_src) AS min_src, MAX(svc_src) AS max_src,
  MIN(FIC_MIS_DATE) AS min_forced, MAX(FIC_MIS_DATE) AS max_forced,
  COUNT(*) AS n_rows,
  COUNTIF(FIC_MIS_DATE IS DISTINCT FROM FIC_MIS_DATE_aux) AS n_aux_ko,
  COUNTIF(REGEXP_CONTAINS(V_ACCOUNT_NUMBER, r'[\r\n]') OR REGEXP_CONTAINS(V_DATA_ORIGIN, r'[\r\n]') OR REGEXP_CONTAINS(V_FCY_CODE, r'[\r\n]')) AS n_newline,
