  0 AS n_amla_exp
FROM (
SELECT * REPLACE (
    LAST_DAY(FIC_MIS_DATE) AS FIC_MIS_DATE,
    REGEXP_REPLACE(V_ACCOUNT_NUMBER, r'[\r\n]+', ' ') AS V_ACCOUNT_NUMBER,
    REGEXP_REPLACE(V_DATA_ORIGIN, r'[\r\n]+', ' ') AS V_DATA_ORIGIN,
    REGEXP_REPLACE(V_FCY_CODE, r'[\r\n]+', ' ') AS V_FCY_CODE
  ),
