  FALSE AS svc_is_amla,
  FIC_MIS_DATE AS svc_src
FROM `prj-dpu-prd-dpcc-001.bqd_dpu_prd_ew8_edl_fdm_aml_feeding_bzy_0_bqd_edl_fdm_aml_feeding_bzy_bigquery_dataset.int_stg_account_alt_ccy_values_tmp_h`
