  COUNT(*) AS n_rows,
  COUNTIF(FIC_MIS_DATE IS DISTINCT FROM FIC_MIS_DATE_aux) AS n_aux_ko,
  COUNTIF(REGEXP_CONTAINS(V_BUSINESS_CLUSTER, r'[\r\n]') OR REGEXP_CONTAINS(V_BUSINESS_DOMAIN, r'[\r\n]') OR REGEXP_CONTAINS(V_DATA_JURISDICTION, r'[\r\n]') OR REGEXP_CONTAINS(V_DATA_ORIGIN, r'[\r\n]') OR REGEXP_CONTAINS(V_WATCHLIST_ID, r'[\r\n]') OR REGEXP_CONTAINS(V_WATCHLIST_MEMBER_ID, r'[\r\n]') OR REGEXP_CONTAINS(V_WATCHLIST_MEMBER_TYPE, r'[\r\n]') OR REGEXP_CONTAINS(V_WATCH_LIST_ENTRY_DESC, r'[\r\n]') OR REGEXP_CONTAINS(V_WATCH_LIST_REASON_CD, r'[\r\n]') OR REGEXP_CONTAINS(V_WATCH_LIST_SOURCE_CD, r'[\r\n]')) AS n_newline,
  COUNTIF(FALSE) AS n_pipe,
  (SELECT COUNT(*) FROM `prj-dpu-prd-dpcc-001.bqd_dpu_prd_ew8_edl_fdm_aml_feeding_bzy_0_bqd_edl_fdm_aml_feeding_bzy_bigquery_dataset.int_stg_watchlist_member_entry_tmp_h`) AS rows_src_total,
