    REGEXP_REPLACE(V_WATCH_LIST_REASON_CD, r'[\r\n]+', ' ') AS V_WATCH_LIST_REASON_CD,
    REGEXP_REPLACE(V_WATCH_LIST_SOURCE_CD, r'[\r\n]+', ' ') AS V_WATCH_LIST_SOURCE_CD
