)
GROUP BY is_amla, grp_month
),
g2 AS (
  SELECT g.*,
    CASE grp_month
      WHEN DATE '2026-01-01' THEN DATE '2026-01-31'
      WHEN DATE '2026-02-01' THEN DATE '2026-02-28'
      WHEN DATE '2026-03-01' THEN DATE '2026-03-31'
      WHEN DATE '2026-04-01' THEN DATE '2026-04-30'
      WHEN DATE '2026-05-01' THEN DATE '2026-05-31'
    END AS exp_forced
  FROM g
),
g3 AS (
  SELECT g2.*,
    (min_forced IS NOT DISTINCT FROM max_forced
     AND min_forced IS NOT DISTINCT FROM exp_forced
     AND exp_forced IS NOT NULL
     AND (NOT is_amla OR n_rows = n_amla_exp)) AS grp_ok
  FROM g2
),
t AS (
  SELECT stg,
    ANY_VALUE(rows_src_total) AS righe_src,
    SUM(IF(NOT is_amla, n_rows, 0)) AS righe_base_out,
    SUM(IF(is_amla, n_rows, 0)) AS righe_amla_out,
    ANY_VALUE(n_amla_exp) * 5 AS righe_amla_attese,
    COUNTIF(NOT is_amla) AS n_gruppi_base,
    COUNTIF(is_amla) AS n_gruppi_amla,
    SUM(n_aux_ko) AS aux_ko,
    SUM(n_newline) AS righe_con_acapo,
    SUM(n_pipe) AS righe_con_pipe,
    COUNTIF(NOT grp_ok) AS gruppi_ko,
    ANY_VALUE(n_amla_exp) AS n_amla_exp,
    ARRAY_AGG(FORMAT('%s %s | src %s..%s -> %s | righe %d | %s',
      IF(is_amla, 'AMLA', 'BASE'), IFNULL(FORMAT_DATE('%Y-%m', grp_month), '?'),
      IFNULL(CAST(min_src AS STRING), '-'), IFNULL(CAST(max_src AS STRING), '-'),
      IFNULL(CAST(min_forced AS STRING), '-') || IF(min_forced IS NOT DISTINCT FROM max_forced, '', '..' || IFNULL(CAST(max_forced AS STRING), '-')),
      n_rows, IF(grp_ok, 'OK', 'KO'))
      ORDER BY is_amla, grp_month) AS gruppi_date
  FROM g3
  GROUP BY stg
),
r AS (
  SELECT stg,
    IF(righe_base_out = IFNULL(righe_src, righe_base_out) AND n_gruppi_base = IF(stg = 'stg_party_other_names', 0, 5)
       AND righe_amla_out = righe_amla_attese AND n_gruppi_amla = IF(n_amla_exp > 0, 5, 0)
       AND gruppi_ko = 0
       AND aux_ko = 0 AND righe_con_acapo = 0 AND righe_con_pipe = 0, 'OK', 'KO') AS esito,
    righe_src, righe_base_out, righe_amla_out, righe_amla_attese, n_gruppi_base, n_gruppi_amla,
    aux_ko, righe_con_acapo, righe_con_pipe,
    ARRAY_TO_STRING([
      IF(righe_base_out != IFNULL(righe_src, righe_base_out), 'righe_base<>src', NULL),
      IF(n_gruppi_base != IF(stg = 'stg_party_other_names', 0, 5), 'mesi_base', NULL),
      IF(righe_amla_out != righe_amla_attese, 'righe_amla', NULL),
      IF(n_gruppi_amla != IF(n_amla_exp > 0, 5, 0), 'mesi_amla', NULL),
      IF(gruppi_ko > 0, 'data_forzata', NULL),
      IF(aux_ko > 0, 'aux', NULL),
      IF(righe_con_acapo > 0, 'acapo', NULL),
      IF(righe_con_pipe > 0, 'pipe', NULL)], ', ') AS ko_dettaglio,
    gruppi_date
  FROM t
)
SELECT * FROM (
  SELECT '*** TOTALE ***' AS stg,
    IF(COUNT(*) = 30 AND COUNTIF(esito = 'KO') = 0, 'OK', 'KO') AS esito,
    CAST(NULL AS INT64) AS righe_src, CAST(NULL AS INT64) AS righe_base_out, CAST(NULL AS INT64) AS righe_amla_out,
    CAST(NULL AS INT64) AS righe_amla_attese, CAST(NULL AS INT64) AS n_gruppi_base, CAST(NULL AS INT64) AS n_gruppi_amla,
    CAST(NULL AS INT64) AS aux_ko, CAST(NULL AS INT64) AS righe_con_acapo, CAST(NULL AS INT64) AS righe_con_pipe,
    FORMAT('%d tabelle (attese 30), %d KO', COUNT(*), COUNTIF(esito = 'KO')) AS ko_dettaglio,
    CAST([] AS ARRAY<STRING>) AS gruppi_date
  FROM r
  UNION ALL
  SELECT * FROM r
)
ORDER BY IF(stg LIKE '***%', 0, 1), esito, stg;
